begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.date_act_as(uid text) returns void language sql as $$
select set_config('request.jwt.claims',json_build_object('sub',uid,'role','authenticated')::text,true);
$$;
insert into core.workspaces(id,slug,name) values('eeeeeeee-2111-0023-0099-000000000001','received-date-other-workspace','Date test other workspace');
insert into sales.leads(id,workspace_id,source_channel,raw_name) values('eeeeeeee-2111-0023-0099-000000000002','eeeeeeee-2111-0023-0099-000000000001','other','Other workspace enquiry');
-- Deliberately cross a KL day boundary and reporting period.
set local role authenticated;
select pg_temp.date_act_as('aaaaaaaa-0000-0000-0000-000000000003');
select lives_ok($$select api.create_manual_inquiry('{"source_channel":"other","raw_name":"Received date regression","received_at":"2025-01-01T00:05:00+08:00","owner_id":"aaaaaaaa-0000-0000-0000-000000000003"}','eeeeeeee-2111-0023-0001-000000000001')$$,'capture a historical enquiry');
select is((select received_at from api.leads where raw_name='Received date regression'),'2025-01-01T00:05:00+08'::timestamptz,'actual enquiry date is stored');
select is((select created_at from api.leads where raw_name='Received date regression'),now(),'system entry remains now');
select is((select first_response_due_at from api.leads where raw_name='Received date regression'),'2025-01-01T04:05:00+08'::timestamptz,'response deadline follows actual receipt');
select is((select received_at from api.inbox_leads where raw_name='Received date regression'),'2025-01-01T00:05:00+08'::timestamptz,'inbox exposes receipt separately');
select lives_ok($$select api.work_inquiry((select id from api.leads where raw_name='Received date regression'),'whatsapp_sent','eeeeeeee-2111-0023-0001-000000000002',p_occurred_at=>'2025-01-01T00:15:00+08')$$,'WhatsApp before entry time but after receipt succeeds');
select is((select first_whatsapp_sent_at from api.leads where raw_name='Received date regression'),'2025-01-01T00:15:00+08'::timestamptz,'WhatsApp preserves the historical event time');
select throws_like($$select api.work_inquiry((select id from api.leads where raw_name='Received date regression'),'whatsapp_sent',gen_random_uuid(),p_occurred_at=>'2025-01-01T00:04:59+08')$$,'%earlier than the enquiry received date%','action before receipt is rejected clearly');
select throws_like($$select api.work_inquiry((select id from api.leads where raw_name='Received date regression'),'whatsapp_sent',gen_random_uuid(),p_occurred_at=>now()+interval '1 day')$$,'%Invalid channel or event time%','future action remains rejected');
select is((select median_response_minutes from api.report_lead_source('2025-01-01','2025-01-01') where source_channel='other'),10.0,'response duration and KL report day use actual receipt');
select is((api.funnel_history('2025-01-01','2025-01-01','2025-01-02','leads',1)->>'total')::int,1,'funnel history includes historical receipt cohort');
select is((api.funnel_history('2024-12-31','2024-12-31','2025-01-02','leads',1)->>'total')::int,0,'KL receipt is excluded from previous UTC date');
select throws_like($$update api.leads set created_at=now()-interval '1 day' where raw_name='Received date regression'$$,'%System entry time cannot be changed%','system entry is immutable');
select throws_like($$update api.leads set received_at=received_at-interval '1 hour' where raw_name='Received date regression'$$,'%correction action%','direct date edits require the audited command');
select lives_ok($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'2024-12-31T23:55:00+08','2025-01-01T00:05:00+08','Corrected against original message','eeeeeeee-2111-0023-0001-000000000003')$$,'owner corrects enquiry date');
select lives_ok($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'2024-12-31T23:55:00+08','2025-01-01T00:05:00+08','Corrected against original message','eeeeeeee-2111-0023-0001-000000000003')$$,'retry returns original result despite stale expected date');
select is((select count(*)::int from api.activities where lead_id=(select id from api.leads where raw_name='Received date regression') and metadata->>'event'='inquiry_received_date'),1,'retry creates one audit activity');
select ok((select metadata->'before'->>'received_at' is not null and metadata->'after'->>'received_at' is not null and actor_id=auth.uid() and body='Corrected against original message' from api.activities where lead_id=(select id from api.leads where raw_name='Received date regression') and metadata->>'event'='inquiry_received_date'),'history preserves before/after, actor and reason');
select is((select created_at from api.leads where raw_name='Received date regression'),now(),'correction preserves system entry');
select is((select first_response_due_at from api.leads where raw_name='Received date regression'),'2025-01-01T03:55:00+08'::timestamptz,'correction shifts response deadline');
select is((select median_response_minutes from api.report_lead_source('2024-12-31','2024-12-31') where source_channel='other'),20.0,'report moves to corrected cohort and duration');
select is((api.funnel_history('2024-12-31','2024-12-31','2025-01-02','leads',1)->>'total')::int,1,'funnel history moves to corrected cohort');
select throws_like($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'2025-01-01T00:00:00+08','2025-01-01T00:05:00+08','Stale correction attempt',gen_random_uuid())$$,'%changed since you opened%','stale correction cannot overwrite another edit');
select throws_like($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'2025-01-01T00:16:00+08','2024-12-31T23:55:00+08','Would invalidate WhatsApp history',gen_random_uuid())$$,'%cannot be later than an existing customer action%','correction cannot invalidate historical WhatsApp');
select throws_like($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),now()+interval '1 day','2024-12-31T23:55:00+08','Future date attempt',gen_random_uuid())$$,'%not in the future%','future receipt is rejected');
select throws_like($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'infinity','2024-12-31T23:55:00+08','Infinite date attempt',gen_random_uuid())$$,'%not in the future%','infinite receipt is rejected');
select throws_like($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'2024-12-31T23:50:00+08','2024-12-31T23:55:00+08','',gen_random_uuid())$$,'%correction reason%','reason is required');
select throws_like($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'2024-12-31T23:50:00+08','2024-12-31T23:55:00+08','Changed payload','eeeeeeee-2111-0023-0001-000000000003')$$,'%Request ID already used%','changed correction cannot reuse a request ID');
reset role;
select throws_like($$delete from sales.activities where lead_id=(select id from api.leads where raw_name='Received date regression') and metadata->>'event'='inquiry_received_date'$$,'%corrections are history%','date-correction history cannot be deleted');
set local role authenticated;
select throws_like($$select api.create_manual_inquiry('{"source_channel":"other","raw_name":"Future date fixture","received_at":"infinity"}',gen_random_uuid())$$,'%not in the future%','manual creation rejects infinite receipt');
select pg_temp.date_act_as('aaaaaaaa-0000-0000-0000-000000000004');
select throws_like($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'2024-12-31T23:50:00+08','2024-12-31T23:55:00+08','Other salesperson correction',gen_random_uuid())$$,'%permission denied%','another salesperson cannot correct an owned enquiry');
select pg_temp.date_act_as('aaaaaaaa-0000-0000-0000-000000000002');
select lives_ok($$select api.correct_inquiry_received_at((select id from api.leads where raw_name='Received date regression'),'2024-12-31T23:50:00+08','2024-12-31T23:55:00+08','Manager verified historical enquiry',gen_random_uuid())$$,'manager can correct owned enquiry');
select pg_temp.date_act_as('aaaaaaaa-0000-0000-0000-000000000003');
select throws_like($$select api.correct_inquiry_received_at('eeeeeeee-2111-0023-0099-000000000002',now()-interval '1 day',now(),'Foreign workspace attempt',gen_random_uuid())$$,'%workspace access denied%','cross-workspace correction is denied');
-- Connector imports preserve actual receipt and physical entry independently.
select lives_ok($$select api.accept_intake('11111111-1111-1111-1111-111111111111','website','enquiry-date-test',null,'enquiry-date:connector:1','{}','{"name":"Connector received regression","phone":"+60178882301"}','2025-02-01T00:05:00+08')$$,'connector imports historical receipt');
select is((select received_at from api.leads where raw_name='Connector received regression'),'2025-02-01T00:05:00+08'::timestamptz,'connector receipt uses source event time');
select is((select created_at from api.leads where raw_name='Connector received regression'),now(),'connector preserves physical entry time');
select lives_ok($$select api.accept_intake('11111111-1111-1111-1111-111111111111','website','enquiry-date-test',null,'enquiry-date:connector:2','{}','{"name":"Second historical connector regression","phone":"+60178882301"}','2025-03-01T00:05:00+08')$$,'same customer can have a separate historical enquiry');
select is((select count(*)::int from api.leads where raw_name in ('Connector received regression','Second historical connector regression')),2,'historical deduplication uses receipt rather than batch entry date');
set local role anon;
select throws_like($$select api.correct_inquiry_received_at(gen_random_uuid(),now(),now(),'Anonymous attempt',gen_random_uuid())$$,'%permission denied%','anonymous correction denied');
reset role;
select * from finish();
rollback;
